matched = []
for (i, l) in enumerate(src.open(), 1):
    r = json.loads(l)
    if r.get('pmid') == '32252728':
        matched.append(dict(pmid=r['pmid'], doi=r['doi'], title=r['title'], abstract=r['abstractText'], source_path=str(src), line=i, record_sha256=hashlib.sha256(l.encode()).hexdigest()))
