assert '80 in the posterior mandible' in matched[0]['abstract'] and 'Five cases with transient paresthesia' in matched[0]['abstract']
dump(P / 'raw/LOCAL_CLINICAL_RECORD.json', matched[0])

def ci(k, n):
    return [0.0 if k == 0 else float(beta.ppf(0.025, k, n - k + 1)), 1.0 if k == n else float(beta.ppf(0.975, k + 1, n - k))]
